  function saveTech(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));const old=e.currentTarget.dataset.id;const tech={id:d.id.trim().toUpperCase(),name:d.name.trim(),specialty:d.specialty,region:d.region,available:d.available==='true'};if(old){Object.assign(state.techs.find(t=>t.id===old),tech)}else{if(state.techs.some(t=>t.id===tech.id)){toast('Já existe um técnico com essa identificação.','error');return}state.techs.push(tech)}save();closeModal();render();toast(old?'Dados do técnico atualizados.':'Técnico cadastrado.')}
